actions.command:
cat > /tmp/rogue-agent.conf << 'CONF'
agent {
  data_dir = "/tmp/rogue-spire-agent"
  log_level = "DEBUG"
  server_address = "spire-server"
  server_port = "8081"
  socket_path = "/tmp/rogue-agent.sock"
  trust_domain = "example.org"
}

plugins {
  NodeAttestor "join_token" {
    plugin_data {
    }
  }
  KeyManager "disk" {
    plugin_data {
      directory = "/tmp/rogue-spire-agent"
    }
  }
  WorkloadAttestor "unix" {
    plugin_data {
    }
  }
}
CONF
